// WasmEngine: adapter over the wasm-bindgen build of relay-wasm (./pkg/relay_wasm.js).
//
// The pkg is generated by `wasm-pack build crates/relay-wasm --target web --out-dir
// ../../web/src/core/pkg`. It is optional at build time: import.meta.glob returns an empty
// map when the file does not exist, and the client falls back to the MockEngine.
//
// The adapter is lenient about return shapes: JSON strings are parsed, `undefined` maps to
// null, and arrays of byte arrays may come back as a JS array of Uint8Array.

import type {
  AppMessage,
  CompactLink,
  Contact,
  Engine,
  EngineFactory,
  EnvelopeHeader,
  Group,
  Inbound,
} from './engine'
import { RelayError } from './engine'
import { toHex } from '../lib/bytes'

/* The raw wasm-bindgen object. Typed loosely on purpose: the pkg may not exist yet. */
type Raw = Record<string, (...args: unknown[]) => unknown> & { free?: () => void }
interface RawClass {
  create(name: string): Raw
  restore(state: Uint8Array): Raw
}
interface PkgModule {
  default: (input?: unknown) => Promise<unknown>
  RelayEngine: RawClass
}

const pkgLoaders = import.meta.glob('./pkg/relay_wasm.js')

export const wasmAvailable = (): boolean => Object.keys(pkgLoaders).length > 0

function json<T>(v: unknown): T {
  if (typeof v === 'string') return JSON.parse(v) as T
  return v as T
}

function bytes(v: unknown): Uint8Array {
  if (v instanceof Uint8Array) return v
  if (Array.isArray(v)) return new Uint8Array(v as number[])
  if (v instanceof ArrayBuffer) return new Uint8Array(v)
  throw new RelayError('Malformed', 'expected bytes from the core')
}

function byteList(v: unknown): Uint8Array[] {
  if (Array.isArray(v)) return v.map(bytes)
  if (typeof v === 'string') return (JSON.parse(v) as number[][]).map((a) => new Uint8Array(a))
  return []
}

function strings(v: unknown): string[] {
  if (Array.isArray(v)) return v.map(String)
  if (typeof v === 'string') return v.startsWith('[') ? (JSON.parse(v) as string[]) : v.split(/\s+/)
  return []
}

const ERROR_CODES = ['InvalidCard', 'KeyChanged', 'NoSession', 'Decrypt', 'Malformed', 'Unknown', 'Storage', 'Group'] as const

function wrapError(e: unknown): RelayError {
  if (e instanceof RelayError) return e
  const msg = e instanceof Error ? e.message : String(e)
  const code = ERROR_CODES.find((c) => msg.includes(c)) ?? 'Unknown'
  return new RelayError(code, msg)
}

class WasmEngineImpl implements Engine {
  readonly kind = 'wasm' as const
  constructor(private raw: Raw) {}

  private call(name: string, ...args: unknown[]): unknown {
    const fn = this.raw[name]
    if (typeof fn !== 'function') throw new RelayError('Unknown', `core method ${name} missing`)
    try {
      return fn.apply(this.raw, args)
    } catch (e) {
      throw wrapError(e)
    }
  }

  exportState = () => bytes(this.call('exportState'))
  fingerprintHex = () => String(this.call('fingerprintHex'))
  safetyWords = () => strings(this.call('safetyWords'))
  mailboxHex = () => String(this.call('mailboxHex'))
  displayName = () => String(this.call('displayName'))
  setDisplayName = (name: string) => void this.call('setDisplayName', name)
  myCard = (nodeUrl?: string | null, handle?: string | null) =>
    String(this.call('myCard', nodeUrl ?? undefined, handle ?? undefined))
  myCompactLink = (nodeUrl?: string | null) => String(this.call('myCompactLink', nodeUrl ?? undefined))
  deviceSigningPublic = () => bytes(this.call('deviceSigningPublic'))
  signNodeChallenge = (nonce: Uint8Array) => bytes(this.call('signNodeChallenge', nonce))
  rotatePrekeyIfDue = (nowMs: number) => Boolean(this.call('rotatePrekeyIfDue', BigInt(nowMs)))

  addContact = (card: string) => json<Contact>(this.call('addContact', card))
  addContactReplacing = (card: string) => json<Contact>(this.call('addContactReplacing', card))
  parseCompactLink = (link: string) => json<CompactLink>(this.call('parseCompactLink', link))
  contacts = () => json<Contact[]>(this.call('contacts'))
  removeContact = (fp: string) => void this.call('removeContact', fp)
  setVerified = (fp: string, v: boolean) => void this.call('setVerified', fp, v)
  renameContact = (fp: string, name: string) => void this.call('renameContact', fp, name)
  contactSafetyWords = (fp: string) => strings(this.call('contactSafetyWords', fp))
  contactSafetyCode = (fp: string) => String(this.call('contactSafetyCode', fp))

  encryptFor = (fp: string, m: AppMessage) => bytes(this.call('encryptFor', fp, JSON.stringify(m)))
  meshTagFor = (fp: string, nowMs: number) => bytes(this.call('meshTagFor', fp, BigInt(nowMs)))
  retagForMesh = (env: Uint8Array, fp: string, nowMs: number) =>
    bytes(this.call('retagForMesh', env, fp, BigInt(nowMs)))
  open = (env: Uint8Array, nowMs: number): Inbound | null => {
    const r = this.call('open', env, BigInt(nowMs))
    if (r === undefined || r === null || r === '') return null
    return json<Inbound>(r)
  }

  createGroup = (name: string, fps: string[]) => String(this.call('createGroup', name, fps))
  groupEncrypt = (gid: string, m: AppMessage) => byteList(this.call('groupEncrypt', gid, JSON.stringify(m)))
  groups = () => json<Group[]>(this.call('groups'))
  groupAdd = (gid: string, fp: string) => byteList(this.call('groupAdd', gid, fp))
  groupRemove = (gid: string, fp: string) => byteList(this.call('groupRemove', gid, fp))
  leaveGroup = (gid: string) => void this.call('leaveGroup', gid)

  channelEncrypt = (name: string, pw: string | null, m: AppMessage) =>
    bytes(this.call('channelEncrypt', name, pw ?? undefined, JSON.stringify(m)))
  joinChannel = (name: string, pw: string | null) => void this.call('joinChannel', name, pw ?? undefined)
  leaveChannel = (name: string) => void this.call('leaveChannel', name)

  sealAttachment = (plain: Uint8Array) => bytes(this.call('sealAttachment', plain))
  openAttachment = (key: Uint8Array, sha: Uint8Array, ct: Uint8Array) =>
    bytes(this.call('openAttachment', key, sha, ct))

  callKey = (fp: string, callId: string) => bytes(this.call('callKey', fp, callId))

  /** Postcard v1 envelope: v u8, kind u8, tag [u8;16], ttl u8, id [u8;16], body. */
  envelopeHeader(env: Uint8Array): EnvelopeHeader | null {
    if (env.length < 35 || env[0] !== 1) return null
    return { kind: env[1], tag: toHex(env.slice(2, 18)), id: toHex(env.slice(19, 35)) }
  }
}

export async function loadWasmFactory(): Promise<EngineFactory | null> {
  const loader = pkgLoaders['./pkg/relay_wasm.js']
  if (!loader) return null
  try {
    const mod = (await loader()) as PkgModule
    await mod.default()
    const cls = mod.RelayEngine
    return {
      kind: 'wasm',
      create: (name) => {
        try {
          return new WasmEngineImpl(cls.create(name))
        } catch (e) {
          throw wrapError(e)
        }
      },
      restore: (state) => {
        try {
          return new WasmEngineImpl(cls.restore(state))
        } catch (e) {
          throw wrapError(e)
        }
      },
    }
  } catch (e) {
    console.error('relay-wasm failed to load, falling back to the mock engine', e)
    return null
  }
}
